const maxChunkSize = 4000;
const fullText = $json.output || "";

// The model writes *bold* and _italic_ using plain characters, which is
// fragile: if it ever leaves one unmatched (very common with repo names
// containing underscores), Telegram's Markdown parser rejects the whole
// message with "can't parse entities". To make this bulletproof, we do NOT
// rely on the model's own markdown being balanced. Instead: escape any raw
// HTML special characters first, then deterministically convert *word* and
// _word_ pairs into proper <b> / <i> tags ourselves. Any leftover stray
// asterisk/underscore that never found a partner is simply left as a plain,
// harmless character (Telegram's HTML mode does not error on stray text).
function toTelegramHtml(text) {
  let out = text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

  // *bold* -> <b>bold</b> (single line only, non-greedy)
  out = out.replace(/\*([^\n*]+?)\*/g, "<b>$1</b>");

  // _italic_ -> <i>italic</i>, but never inside a word (avoids breaking
  // underscores that are part of repo names or URLs like owner/repo_name)
  out = out.replace(/(^|[^a-zA-Z0-9_])_([^\n_]+?)_(?![a-zA-Z0-9_])/g, "$1<i>$2</i>");

  return out;
}

const htmlText = toTelegramHtml(fullText);

// Split on paragraph boundaries (blank lines) so a chunk never cuts
// an HTML tag in half.
const paragraphs = htmlText.split(/\n\n+/).filter(p => p.trim().length > 0);
const chunks = [];
let current = "";

for (const para of paragraphs) {
  const candidate = current ? current + "\n\n" + para : para;

  if (candidate.length > maxChunkSize && current) {
    chunks.push({ json: { chunk: current } });
    current = para;
  } else {
    current = candidate;
  }

  // Edge case: a single paragraph is itself longer than maxChunkSize.
  while (current.length > maxChunkSize) {
    chunks.push({ json: { chunk: current.substring(0, maxChunkSize) } });
    current = current.substring(maxChunkSize);
  }
}

if (current) {
  chunks.push({ json: { chunk: current } });
}

return chunks;
